head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setArray]<br/>Column 정보와 Row 데이터 객체를 사용하여 DataList 모듈의 데이터를 새로 설정하거나 추가합니다.",
    "validation" : [        
        "objData(필수) 파라미터로 DataList 모듈에 정의된 Column ID 와 새로 설정하거나 추가할 데이터를 각각 배열로 갖는 객체로 설정합니다.",        
        "objData.columnInfo(선택) 파라미터로 data 파라미터의 데이터와 매칭될 Column 의 ID 를 1차원 배열로 설정합니다.",
        "objData.columnInfo(선택) 파라미터를 설정하지 않으면 DataList 모듈에 정의된 Column 이 순서대로 모두 적용됩니다.",
        "objData.data(필수) 파라미터로 새로 설정하거나 추가할 데이터를 1차원 배열로 설정합니다.",
        "objData.data(필수) 파라미터 설정 시 배열의 원소 갯수는 columnInfo 파라미터에 설정한 Column 갯수의 배수와 일치해야 합니다.",
        "새로 설정되거나 추가된 데이터의 Row 상태값은 'R' 로 설정됩니다.",
        "setArray() 메소드 실행 시 DataList 에 적용되어 있던 필터링/정렬은 모두 해제됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}



scwin.btn_getAllJSON_onclick = function (e) {
    let rtn = target1.getAllJSON();
    let jsonString = JSON.stringify(rtn);

	// wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
	wf_body_bottom.getObj("scwin").setReturnValue("result.json: " + jsonString);
};



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})    
    target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("col1", 1);
};



scwin.btn_setArray_onclick = function (e) {
    let objData = {};

    if (objData.columnInfo == []) {
        objData.data = eval('{' + par_data.getText() + '}');
    }
    else {
        objData.columnInfo = eval('{' + par_columnInfo.getText() + '}');
        objData.data = eval('{' + par_data.getText() + '}');        
    }

    target1.setArray(objData);

    scwin.btn_getAllJSON_onclick();
};
